/*
 * eqthiscall.h - EQ_METHOD: call a client __thiscall method at a fixed VA as a real __thiscall call (C++ only;
 * eqaddr.h includes it). Generated by a script (not published) from the thiscall call sites; keep the generated form.
 *
 *     EQ_METHOD(n, ret, va, (this_type, A1, ..., An), obj)(a1, ..., an)      (n: the number of A's)
 *
 * casts obj to eqd_tc<n><va, ret, this_type, A1, ..., An> and calls its member m(a1, ..., an): ECX = obj, the
 * arguments on the stack, nothing in EDX. EQ_THISCALL (a __fastcall pointer with a dummy EDX argument, the only
 * way in C) costs every call an `xor edx, edx` the original does not have.
 * m is only declared, so the call is `call rel32` to a symbol whose name carries va: the match build maps it to
 * va (compare's coff.eqd_va), DLL builds (test and hook DLLs) link a generated `mov eax, va; jmp eax` for it
 * (tools/unicorn/eqd_unicorn/thiscall_stubs.py; any m defined here gets inlined by VC6, which can reorder the
 * evaluation of the arguments). A void method's m returns int (VC6 rejects `return f();` of a void f in a template); callers ignore
 * EAX either way, so the code is the same. The arguments must reach m directly: a wrapper that takes them
 * again (an operator() with the old argument list) makes VC6 copy them through stack temporaries.
 */
#ifndef TRILOGY_EQTHISCALL_H
#define TRILOGY_EQTHISCALL_H

template<class R> struct eqd_ret { typedef R type; };
template<> struct eqd_ret<void> { typedef int type; };

template<unsigned VA, class R, class T> struct eqd_tc0 {
    typename eqd_ret<R>::type m();
};
#define EQD_P0(t) t

template<unsigned VA, class R, class T, class A1> struct eqd_tc1 {
    typename eqd_ret<R>::type m(A1);
};
#define EQD_P1(t, a1) t, a1

template<unsigned VA, class R, class T, class A1, class A2> struct eqd_tc2 {
    typename eqd_ret<R>::type m(A1, A2);
};
#define EQD_P2(t, a1, a2) t, a1, a2

template<unsigned VA, class R, class T, class A1, class A2, class A3> struct eqd_tc3 {
    typename eqd_ret<R>::type m(A1, A2, A3);
};
#define EQD_P3(t, a1, a2, a3) t, a1, a2, a3

template<unsigned VA, class R, class T, class A1, class A2, class A3, class A4> struct eqd_tc4 {
    typename eqd_ret<R>::type m(A1, A2, A3, A4);
};
#define EQD_P4(t, a1, a2, a3, a4) t, a1, a2, a3, a4

template<unsigned VA, class R, class T, class A1, class A2, class A3, class A4, class A5> struct eqd_tc5 {
    typename eqd_ret<R>::type m(A1, A2, A3, A4, A5);
};
#define EQD_P5(t, a1, a2, a3, a4, a5) t, a1, a2, a3, a4, a5

template<unsigned VA, class R, class T, class A1, class A2, class A3, class A4, class A5, class A6> struct eqd_tc6 {
    typename eqd_ret<R>::type m(A1, A2, A3, A4, A5, A6);
};
#define EQD_P6(t, a1, a2, a3, a4, a5, a6) t, a1, a2, a3, a4, a5, a6

template<unsigned VA, class R, class T, class A1, class A2, class A3, class A4, class A5, class A6, class A7> struct eqd_tc7 {
    typename eqd_ret<R>::type m(A1, A2, A3, A4, A5, A6, A7);
};
#define EQD_P7(t, a1, a2, a3, a4, a5, a6, a7) t, a1, a2, a3, a4, a5, a6, a7

template<unsigned VA, class R, class T, class A1, class A2, class A3, class A4, class A5, class A6, class A7, class A8> struct eqd_tc8 {
    typename eqd_ret<R>::type m(A1, A2, A3, A4, A5, A6, A7, A8);
};
#define EQD_P8(t, a1, a2, a3, a4, a5, a6, a7, a8) t, a1, a2, a3, a4, a5, a6, a7, a8

template<unsigned VA, class R, class T, class A1, class A2, class A3, class A4, class A5, class A6, class A7, class A8, class A9> struct eqd_tc9 {
    typename eqd_ret<R>::type m(A1, A2, A3, A4, A5, A6, A7, A8, A9);
};
#define EQD_P9(t, a1, a2, a3, a4, a5, a6, a7, a8, a9) t, a1, a2, a3, a4, a5, a6, a7, a8, a9

template<unsigned VA, class R, class T, class A1, class A2, class A3, class A4, class A5, class A6, class A7, class A8, class A9, class A10> struct eqd_tc10 {
    typename eqd_ret<R>::type m(A1, A2, A3, A4, A5, A6, A7, A8, A9, A10);
};
#define EQD_P10(t, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10) t, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10

template<unsigned VA, class R, class T, class A1, class A2, class A3, class A4, class A5, class A6, class A7, class A8, class A9, class A10, class A11> struct eqd_tc11 {
    typename eqd_ret<R>::type m(A1, A2, A3, A4, A5, A6, A7, A8, A9, A10, A11);
};
#define EQD_P11(t, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11) t, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11

template<unsigned VA, class R, class T, class A1, class A2, class A3, class A4, class A5, class A6, class A7, class A8, class A9, class A10, class A11, class A12> struct eqd_tc12 {
    typename eqd_ret<R>::type m(A1, A2, A3, A4, A5, A6, A7, A8, A9, A10, A11, A12);
};
#define EQD_P12(t, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12) t, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12

template<unsigned VA, class R, class T, class A1, class A2, class A3, class A4, class A5, class A6, class A7, class A8, class A9, class A10, class A11, class A12, class A13> struct eqd_tc13 {
    typename eqd_ret<R>::type m(A1, A2, A3, A4, A5, A6, A7, A8, A9, A10, A11, A12, A13);
};
#define EQD_P13(t, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, a13) t, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, a13

template<unsigned VA, class R, class T, class A1, class A2, class A3, class A4, class A5, class A6, class A7, class A8, class A9, class A10, class A11, class A12, class A13, class A14> struct eqd_tc14 {
    typename eqd_ret<R>::type m(A1, A2, A3, A4, A5, A6, A7, A8, A9, A10, A11, A12, A13, A14);
};
#define EQD_P14(t, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, a13, a14) t, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, a13, a14

#define EQ_METHOD(n, ret, va, params, obj) ((eqd_tc##n<va, ret, EQD_P##n params> *)(obj))->m

#endif /* TRILOGY_EQTHISCALL_H */
